ep_provider_status.versaScript:
import mediacloud;
vdb import *;

let assetCollection = str(service.env.MEDIA_ASSET_COLLECTION ?? "media_assets").trim();
let assets = vdb.collection(assetCollection);
let recentLookup = assets.find({}, 5);
let recentAssets = recentLookup.data ?? [];
return {
  ok: true,
  assetCollection: assetCollection,
  recentAssetCount: leng(recentAssets),
  mediaCloud: mediacloud.status()
};

ep_upload_cloudinary.versaScript:
import mediacloud;
vdb import *;
crypto import *;
datetime import *;

let req = params;
let upload = mediacloud.upload({provider: "cloudinary", body: req.body ?? {}, auth: req.auth ?? {}});
if (!(upload.ok == true)) {
  return upload;
}
let assetCollection = str(service.env.MEDIA_ASSET_COLLECTION ?? "media_assets").trim();
let assets = vdb.collection(assetCollection);
let actor = str((req.auth ?? {}).username ?? (req.auth ?? {}).sub ?? "system").trim();
if (actor == "") {
  actor = "system";
}
let assetId = crypto.uuid();
let nowTs = datetime.now().isoformat();
let record = {
  assetId: assetId,
  provider: upload.provider,
  providerAssetId: str(upload.providerAssetId ?? "").trim(),
  filename: str(upload.filename ?? "").trim(),
  mimeType: str(upload.mimeType ?? "").trim(),
  storageBucket: str(upload.storageBucket ?? "").trim(),
  storagePath: str(upload.storagePath ?? "").trim(),
  publicUrl: str(upload.publicUrl ?? "").trim(),
  secureUrl: str(upload.secureUrl ?? upload.publicUrl ?? "").trim(),
  sizeBytes: upload.sizeBytes ?? 0,
  status: "uploaded",
  createdAt: nowTs,
  createdBy: actor,
  requestSummary: {sourceType: "mediacloud", providerRoute: "/upload/cloudinary"},
  providerResponse: upload.providerResponse ?? {}
};
let saveRes = assets.insert(record);
if (saveRes.ok == false) {
  return {ok: false, statusCode: 500, reason: saveRes.error ?? "Failed to persist uploaded media metadata", upload: upload, record: record};
}
return {ok: true, statusCode: 201, assetId: assetId, provider: upload.provider, stored: true, upload: upload, record: record};
